import {
  COLORS,
  ERGONOMICS,
  FONT_FAMILIES,
  FONT_SIZES,
  FONT_WEIGHTS,
  ICON_SIZES,
  MOTION,
  RADIUS_BASE_PX,
  RADIUS_SCALE,
  SEMANTIC_COLOR_NAMES,
  SPACING,
  type ColorScheme,
  type FontRole,
  type FontScript,
} from "./tokens";

const NOTE =
  "GENERATED by @ayahloop/design-tokens (pnpm tokens:generate). Do not edit — edit src/tokens.ts.";

function radiusPx(k: number): number {
  return Math.round(RADIUS_BASE_PX * k * 100) / 100;
}

export function renderWebThemeCss(): string {
  const themeLines = [
    ...SEMANTIC_COLOR_NAMES.map((name) => `  --color-${name}: var(--${name});`),
    ...Object.entries(RADIUS_SCALE).map(([step, k]) =>
      k === 1
        ? `  --radius-${step}: var(--radius);`
        : `  --radius-${step}: calc(var(--radius) * ${k});`,
    ),
  ];
  const block = (scheme: ColorScheme, selector: string) => {
    const lines = SEMANTIC_COLOR_NAMES.map((name) => `  --${name}: ${COLORS[scheme][name]};`);
    if (scheme === "light") {
      lines.push(`  --radius: ${RADIUS_BASE_PX / 16}rem;`);
      lines.push(`  --press-scale: ${MOTION.pressScale};`);
      lines.push(`  --duration-fast: ${MOTION.durationFastMs}ms;`);
      lines.push(`  --ease-ios: cubic-bezier(0.32, 0.72, 0, 1);`);
    }
    return `${selector} {\n${lines.join("\n")}\n}\n`;
  };
  return (
    `/* ${NOTE} Target: Tailwind 4 (apps/web). */\n` +
    `@theme inline {\n${themeLines.join("\n")}\n}\n\n` +
    block("light", ":root") +
    "\n" +
    block("dark", ".dark")
  );
}

export function renderTailwindPreset(): string {
  const colors = Object.fromEntries(
    SEMANTIC_COLOR_NAMES.map((name) => [name, `var(--color-${name})`]),
  );
  const fontSize = Object.fromEntries(
    Object.entries(FONT_SIZES).map(([k, v]) => [
      k,
      [`${v.size}px`, { lineHeight: `${v.lineHeight}px` }],
    ]),
  );
  const spacing = Object.fromEntries(Object.entries(SPACING).map(([k, v]) => [k, `${v}px`]));
  const borderRadius = {
    none: "0px",
    ...Object.fromEntries(Object.entries(RADIUS_SCALE).map(([k, v]) => [k, `${radiusPx(v)}px`])),
    full: "9999px",
  };
  const preset = {
    theme: {
      colors: { transparent: "transparent", current: "currentColor", ...colors },
      fontSize,
      spacing,
      borderRadius,
      fontWeight: Object.fromEntries(Object.entries(FONT_WEIGHTS).map(([k, v]) => [k, String(v)])),
      extend: {
        minHeight: {
          touch: `${ERGONOMICS.touchTargetMin}px`,
          control: `${ERGONOMICS.controlHeight}px`,
          primary: `${ERGONOMICS.primaryActionHeight}px`,
        },
        minWidth: { touch: `${ERGONOMICS.touchTargetMin}px` },
        height: {
          control: `${ERGONOMICS.controlHeight}px`,
          "control-sm": `${ERGONOMICS.controlHeightSm}px`,
          primary: `${ERGONOMICS.primaryActionHeight}px`,
        },
      },
    },
  };
  return `/* ${NOTE} Target: Tailwind 3 + NativeWind 4 (apps/mobile). */\nmodule.exports = ${JSON.stringify(preset, null, 2)};\n`;
}

const WEIGHT_FACE = {
  regular: "Regular",
  medium: "Medium",
  semibold: "SemiBold",
  bold: "Bold",
} as const;

function expoFontName(family: string, weight: keyof typeof WEIGHT_FACE): string {
  return `${family.replaceAll(" ", "")}_${FONT_WEIGHTS[weight]}${WEIGHT_FACE[weight]}`;
}

function nativeFontNamesFor(script: FontScript) {
  const roles = Object.keys(FONT_FAMILIES[script]) as FontRole[];
  const weights = Object.keys(WEIGHT_FACE) as (keyof typeof WEIGHT_FACE)[];
  return Object.fromEntries(
    roles.map((role) => [
      role,
      Object.fromEntries(weights.map((w) => [w, expoFontName(FONT_FAMILIES[script][role], w)])),
    ]),
  );
}

const NATIVE_FONT_NAMES = {
  latin: nativeFontNamesFor("latin"),
  arabic: nativeFontNamesFor("arabic"),
};

export function renderNativewindVars(): string {
  const map = (scheme: ColorScheme) =>
    Object.fromEntries(SEMANTIC_COLOR_NAMES.map((name) => [`--color-${name}`, COLORS[scheme][name]]));
  const radii = Object.fromEntries(Object.entries(RADIUS_SCALE).map(([k, v]) => [k, radiusPx(v)]));
  const json = (v: unknown) => JSON.stringify(v, null, 2);
  return (
    `// ${NOTE} Target: NativeWind 4 runtime (apps/mobile).\n` +
    `export const lightVars = ${json(map("light"))} as const;\n\n` +
    `export const darkVars = ${json(map("dark"))} as const;\n\n` +
    `export const palette = { light: lightVars, dark: darkVars } as const;\n\n` +
    `/** Resolved radii in px (base ${RADIUS_BASE_PX}). */\n` +
    `export const radii = ${json(radii)} as const;\n\n` +
    `export const iconSizes = ${json(ICON_SIZES)} as const;\n\n` +
    `export const fontSizes = ${json(FONT_SIZES)} as const;\n\n` +
    `export const fontWeights = ${json(FONT_WEIGHTS)} as const;\n\n` +
    `export const spacing = ${json(SPACING)} as const;\n\n` +
    `export const ergonomics = ${json(ERGONOMICS)} as const;\n\n` +
    `export const motion = ${json(MOTION)} as const;\n\n` +
    `/** Canonical family names per script (see @ayahloop/design-tokens FONT_FAMILIES). */\n` +
    `export const fontFamilies = ${json(FONT_FAMILIES)} as const;\n\n` +
    `/** Expo font export names: fontFamily for RN is one loaded face per weight. */\n` +
    `export const nativeFontNames = ${json(NATIVE_FONT_NAMES)} as const;\n\n` +
    `export type NativeFontScript = keyof typeof nativeFontNames;\n` +
    `export type NativeFontRole = keyof (typeof nativeFontNames)["latin"];\n` +
    `export type NativeFontWeight = keyof (typeof nativeFontNames)["latin"]["sans"];\n`
  );
}

export const GENERATED_FILES: readonly { path: string; render: () => string }[] = [
  { path: "generated/web-theme.css", render: renderWebThemeCss },
  { path: "generated/tailwind-preset.cjs", render: renderTailwindPreset },
  { path: "generated/nativewind-vars.ts", render: renderNativewindVars },
];
